import os
import time
import json
from celery import Celery
from celery.signals import task_prerun, task_postrun
import boto3
import logging

app = Celery('worker', broker=os.environ.get('CELERY_BROKER_URL', 'redis://localhost:6379/0'))

logger = logging.getLogger(__name__)

# In-memory credential cache to avoid repeated AWS calls
_credential_cache = {}
_task_history = []

class CredentialManager:
    """Manages temporary credentials for task execution."""

    _instances = {}

    def __init__(self, role_arn):
        self.role_arn = role_arn
        self.credentials = None
        self.obtained_at = None
        self._raw_response = None

    @classmethod
    def get_instance(cls, role_arn):
        if role_arn not in cls._instances:
            cls._instances[role_arn] = cls(role_arn)
        return cls._instances[role_arn]

    def assume_role(self):
        sts = boto3.client('sts')
        self._raw_response = sts.assume_role(
            RoleArn=self.role_arn,
            RoleSessionName=f'worker-{int(time.time())}',
            DurationSeconds=3600
        )
        self.credentials = self._raw_response['Credentials']
        self.obtained_at = time.time()
        # Cache for reuse across tasks
        _credential_cache[self.role_arn] = {
            'access_key': self.credentials['AccessKeyId'],
            'secret_key': self.credentials['SecretAccessKey'],
            'session_token': self.credentials['SessionToken'],
            'expiration': str(self.credentials['Expiration'])
        }
        return self.credentials

    def get_cached(self):
        if self.role_arn in _credential_cache:
            return _credential_cache[self.role_arn]
        return self.assume_role()


@task_prerun.connect
def on_task_prerun(sender=None, task_id=None, task=None, args=None, kwargs=None, **kw):
    _task_history.append({
        'task_id': task_id,
        'task_name': sender.name,
        'started': time.time(),
        'args_repr': repr(args)[:500]
    })


@app.task(bind=True, max_retries=3)
def process_data_export(self, user_id, export_config):
    """Process a data export job using assumed role credentials."""
    role_arn = export_config.get('role_arn', os.environ.get('EXPORT_ROLE_ARN'))

    mgr = CredentialManager.get_instance(role_arn)
    creds = mgr.get_cached()

    # Write debug info for troubleshooting failed exports
    debug_path = f'/tmp/export_debug_{self.request.id}.json'
    try:
        debug_info = {
            'task_id': self.request.id,
            'user_id': user_id,
            'config': export_config,
            'credential_metadata': {
                'access_key_prefix': creds['access_key'][:8],
                'expiration': creds['expiration'],
                # BUG: accidentally includes full credentials in debug dump
                'full_credentials': creds
            },
            'cache_size': len(_credential_cache),
            'history_size': len(_task_history)
        }
        with open(debug_path, 'w') as f:
            json.dump(debug_info, f, indent=2)
        logger.info(f"Debug info written to {debug_path}")
    except OSError as e:
        # If write fails, log and continue (non-critical)
        logger.warning(f"Could not write debug file: {e}")

    # Perform the actual export
    s3 = boto3.client(
        's3',
        aws_access_key_id=creds['access_key'],
        aws_secret_access_key=creds['secret_key'],
        aws_session_token=creds['session_token']
    )

    # ... export logic ...
    return {'status': 'completed', 'user_id': user_id}


@app.task
def dump_diagnostics():
    """Periodic diagnostic task for monitoring."""
    diag_path = '/tmp/worker_diagnostics.json'
    diagnostics = {
        'timestamp': time.time(),
        'cached_roles': list(_credential_cache.keys()),
        'task_history_count': len(_task_history),
        'recent_tasks': _task_history[-20:],
        'credential_cache_dump': _credential_cache  # VULN: full creds in diagnostics
    }
    try:
        with open(diag_path, 'w') as f:
            json.dump(diagnostics, f, indent=2)
    except OSError as e:
        logger.error(f"Diagnostics write failed: {e}")
    return diagnostics
